namespace Atc.Rest.Api.Generator.Cli.Extractors.TypeScript;

/// <summary>
/// Builds the auto-generated file header for TypeScript files.
/// </summary>
public static class TypeScriptHeaderBuilder
{
    /// <summary>
    /// The first line of every generated TypeScript file. The generation service recognises its own files by this
    /// line alone (to overwrite them, and to delete the ones a later run no longer writes), so it never changes.
    /// </summary>
    public static string AutoGeneratedHeader { get; } = "// <auto-generated />\n";

    /// <summary>
    /// The second line: the version of the tool that wrote the file, for traceability - which runtime a consumer
    /// has, and which build a bug report is about. The snapshot tests scrub it; a consumer who commits the output
    /// sees one line per file change on a tool bump.
    /// </summary>
    public static string VersionLine { get; } = "// atc-rest-api-gen " + GeneratorInfo.Version + "\n";

    /// <summary>
    /// The header of a generated file: <see cref="AutoGeneratedHeader"/> then <see cref="VersionLine"/>.
    /// </summary>
    public static string FileHeader { get; } = AutoGeneratedHeader + VersionLine;
}